using System.Diagnostics;
using System.Text.Json;
using System.IO.Compression;
using DynamicFrontline.Poc030;
using DynamicFrontline.Frontline.Rules023;
public static class FullPipelineBenchmark
{
    public static void Run(string mapFile,string output,int count,int steps,int repeat,bool events=false)
    {
        Directory.CreateDirectory(output);var map=JsonSerializer.Deserialize<MapDescriptor>(File.ReadAllText(mapFile))!;
        if(events){var mask=Enumerable.Repeat(true,map.Width*map.Height).ToArray();map=map with{Map="SyntheticEventSoak_NotAirport",Scenario=null,ActiveZoneId=null,Origin=new(0,0),Scoring=mask,Infantry=mask,Ground=mask,InfantryEdges=null,GroundEdges=null,Roots=[new(0,new(100,100)),new(1,new(6400,6400))],Evidence="Explicit synthetic event workload; not observed game geography"};}
        var binding=Rc2Fixtures.Binding with{Map=map.Map,Players=[new(1,1,101,false),new(2,4,102,false)]};
        var profiles=Rc2Fixtures.Profiles with{BuildFingerprint=map.GameFingerprint,Entries=[new(1,30,1000,true,true,false,1,MoraleClass.Regular,"Synthetic benchmark"),new(2,10,1000,false,false,true,6,MoraleClass.NativePassthrough,"Synthetic benchmark")]};
        var world=new CanonicalWorld(binding,profiles,map,new());var bridge=new ObservationBridge(binding,map,profiles,map.GameFingerprint);
        var terrain=map.Create(map.Map,map.GameFingerprint);var cells=Enumerable.Range(0,map.Scoring.Length).Where(i=>map.Infantry[i]).ToArray();var random=new Random(1700+repeat);var locations=Enumerable.Range(0,count).Select(_=>cells[random.Next(cells.Length)]).ToArray();
        var basename=$"{(events?"events":"full")}-{count}-{map.CellSize}-{repeat}";using var raw=new StreamWriter(new GZipStream(File.Create(Path.Combine(output,basename+".csv.gz")),CompressionLevel.Fastest));
        raw.WriteLine("tick,total_ms,copy_ms,canonical_ms,wire_ms,core_digest_ms,projection_ms,allocated_bytes,working_set,managed_bytes,gc0,gc1,gc2,unknown,prepare_ms,zoc_ms,geometry_ms,victory_ms,encirclement_ms,capture_ms");
        var times=new List<double>();long bytes=0;var process=Process.GetCurrentProcess();long firstMemory=0,lastMemory=0;var watch=Stopwatch.StartNew();var gc=Enumerable.Range(0,3).Select(GC.CollectionCount).ToArray();long startAllocated=GC.GetTotalAllocatedBytes(true);
        for(int tick=-128;tick<steps;tick++){
            int iteration=tick+128;double end=(iteration+1)*.25;long allocation=GC.GetAllocatedBytesForCurrentThread();long stamp=Stopwatch.GetTimestamp();double Lap(){long now=Stopwatch.GetTimestamp();double ms=(now-stamp)*1000d/Stopwatch.Frequency;stamp=now;return ms;}
            Observation Observe(string role){int owner=role=="A"?1:2;var seed=Rc2Fixtures.Observation(role,iteration+1,end);var units=Enumerable.Range(0,count).Where(i=>(events?(i/2)%2+1:i%2+1)==owner).Select(i=>{var p=terrain.Grid.Center(locations[i]);bool infantry=events?i%2==0:i%4<2;if(events){int phase=iteration/600%6;double center=owner==1?1900:4600;int pair=i/4;double angle=pair*2*Math.PI/25;double offset=infantry?0:(phase%2==0?99:101);p=new(center+650*Math.Cos(angle)+offset,3250+650*Math.Sin(angle));if(i<4)p=new(owner==1?4600:1900,3250);if(phase==2&&pair<5&&i>=4)p=new(owner==1?300:6200,300);if(phase==3)p=new(3250+650*Math.Cos(angle)+offset,3250+650*Math.Sin(angle));}
                return seed.Owned[0] with{Stress=events?(iteration/400%3==1?200:800):seed.Owned[0].Stress,ObservedLevel=events?(iteration/400%3==1?0:2):seed.Owned[0].ObservedLevel,NetworkId=i+1,Local=new(1,i,iteration/500+1),Definition=infantry?1:2,Role=infantry?30:10,TeamUid=owner==1?1:4,X=(float)(p.X+(events?0:Math.Sin(iteration*.03+i)*9)),Z=(float)(p.Y+(events?0:Math.Cos(iteration*.03+i)*9)),Soldiers=infantry?8u:0u,Alive=iteration%500!=499,Loaded=infantry&&iteration%120<8};}).ToArray();return seed with{Map=map.Map,Participants=binding.Players,Owned=units,MapState=new(map.Scenario??"","Airport",23,map.Origin.X,map.Origin.Y,map.Width*map.CellSize,map.Height*map.CellSize,"Synthetic observed header for offline benchmark using real extracted static geometry")};}
            var a=Observe("A");var b=Observe("B");double copy=Lap();world.Full("A",a);world.Full("B",b);var health=new SourceHealth(SourceState.LiveComplete,iteration+1,1,end,false,0,"Synthetic benchmark");var input=world.Build(health,health)!;if(events){input=input with{SupplyComplete=true,Services=iteration%600>=300&&iteration%600<340?input.Units.Take(4).Select(u=>new ServiceInterval(u.Key,$"synthetic-{iteration}-{u.Key.Uid}","fixture-service",input.Start,input.End,1,"Repair","Explicit synthetic positive duration, never inferred from native point proof")).ToArray():[]};}double canonical=Lap();
            var encoded=CanonicalCodec.Bytes(input);input=JsonSerializer.Deserialize<CanonicalInput>(encoded)!;double wire=Lap();bridge.Step(input,0);double core=Lap();_=CanonicalCodec.Bytes(bridge.Project(0,true));double projection=Lap();
            if(iteration>0&&iteration%500==0){var checkpoint=bridge.Export();bridge=new(binding,map,profiles,map.GameFingerprint);bridge.Restore(checkpoint);world.Restore(world.Export());}
            double total=copy+canonical+wire+core+projection+Lap();long allocated=GC.GetAllocatedBytesForCurrentThread()-allocation;int unknown=bridge.Last?.Geometry.Count(g=>g.Enclosed==Evidence.Unknown)??count;
            if(tick>=0){times.Add(total);bytes+=allocated;if(tick%100==0){process.Refresh();lastMemory=process.WorkingSet64;if(firstMemory==0)firstMemory=lastMemory;}var t=bridge.Timings;raw.WriteLine(FormattableString.Invariant($"{tick},{total:R},{copy:R},{canonical:R},{wire:R},{core:R},{projection:R},{allocated},{lastMemory},{GC.GetTotalMemory(false)},{GC.CollectionCount(0)},{GC.CollectionCount(1)},{GC.CollectionCount(2)},{unknown},{t?.Prepare??0:R},{t?.Zoc??0:R},{t?.Geometry??0:R},{t?.Victory??0:R},{t?.Encirclement??0:R},{t?.Capture??0:R}"));}
            if(tick>=0&&tick%1000==0){raw.Flush();Console.WriteLine($"{basename}: {tick}/{steps}, elapsed {watch.Elapsed.TotalSeconds:F1}s");}
        }
        times.Sort();double Q(double q)=>times[(int)((times.Count-1)*q)];var report=new{Scope=(events?"SYNTHETIC event soak: mass 99/101m pairs, two rings/gap/merge, actual-stress fixture, explicit service intervals, generation/checkpoint. No dynamic topology claim. ":"")+"Copied synthetic owner observations -> canonical lifecycle -> JSON wire -> existing Observe core/digests -> own projection serialization. Map topology identified by MapHash; synthetic event map when events=true. NO game/TLS/HUD/disk time included in total; CSV disk outside timing.",MapHash=map.Hash,Count=count,Steps=steps,Repeat=repeat,Warmup=128,Cell=map.CellSize,PhysicalSize=new[]{map.Width*map.CellSize,map.Height*map.CellSize},Seed=1700+repeat,Runtime=Environment.Version.ToString(),OS=Environment.OSVersion.ToString(),CPU=Environment.GetEnvironmentVariable("PROCESSOR_IDENTIFIER"),Cores=Environment.ProcessorCount,P50=Q(.5),P95=Q(.95),P99=Q(.99),Max=times[^1],DeadlineMisses=times.Count(t=>t>250),BytesPerStep=bytes/(double)steps,TotalProcessAllocated=GC.GetTotalAllocatedBytes(false)-startAllocated,GC=Enumerable.Range(0,3).Select(i=>GC.CollectionCount(i)-gc[i]).ToArray(),FirstWorkingSet=firstMemory,LastWorkingSet=lastMemory,Queues="Synchronous offline stages; queue occupancy zero by construction; native reads/TLS/HUD require separate measurements",Seconds=watch.Elapsed.TotalSeconds};
        File.WriteAllText(Path.Combine(output,basename+".json"),JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(report));
    }
}
